def _vset(id_,level,topic,unit_ref,items):
    return VocabularySet(id=id_,level=level,topic=topic,unit_ref=unit_ref,words=[VocabularyEntry(word=w,pos=p,definition=d,example=e) for w,p,d,e in items])

