def _units(level,titles,grammar,vocab):
    return [CurriculumUnit(id=f"kk-{level.lower()}-unit-{i}",level=level,unit_number=i,title=t,grammar_points=[g],vocabulary_set_ids=[v],lesson_types=["grammar","vocabulary","listening","speaking","reading","writing","review"],competency_checklist=[f"Use {g} in context",f"Discuss {t} in natural Kazakh"],default_weeks=2) for i,(t,g,v) in enumerate(zip(titles,grammar,vocab),1)]

